/* ============================================================
   XAVIER HAUGHTON STUDIOS — shared styles
   ============================================================ */
:root{
  --black:#111111;
  --gray:#555555;
  --light:#999999;
  --line:#e4e4e4;
  --white:#ffffff;
  --dark:#171311;
  --pad:80px;
  --serif:'Cormorant',Georgia,serif;
  --sans:'Inter',-apple-system,sans-serif;
}
*{margin:0;padding:0;box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{
  background:var(--white);
  color:var(--black);
  font-family:var(--sans);
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
::selection{background:#111;color:#fff;}
a{color:inherit;}

/* ---------- NAV ---------- */
nav{
  position:fixed;top:0;left:0;right:0;z-index:100;
  display:flex;justify-content:space-between;align-items:center;
  padding:28px var(--pad);
  transition:background .5s ease, backdrop-filter .5s ease, padding .4s ease;
}
nav .wordmark{
  font-family:var(--serif);font-weight:500;font-size:22px;letter-spacing:.04em;
  color:var(--black);text-decoration:none;line-height:1;white-space:nowrap;
  transition:color .5s ease;z-index:2;
}
nav.on-dark .wordmark{color:#fff;}
nav .nav-right{display:flex;align-items:center;}
.menu-trigger{
  background:none;border:none;cursor:pointer;
  font-family:var(--sans);font-size:12px;letter-spacing:.14em;text-transform:uppercase;
  color:var(--black);opacity:.85;transition:opacity .15s ease, color .5s ease;padding:0;
}
nav.on-dark .menu-trigger{color:#fff;}
.menu-trigger:hover{opacity:.45;}
nav .menu{
  display:flex;gap:34px;align-items:center;overflow:hidden;
  max-width:0;opacity:0;
  transition:max-width .6s cubic-bezier(.2,.6,.2,1), opacity .4s ease;
  pointer-events:none;
}
nav .menu a{
  font-family:var(--sans);font-size:12px;letter-spacing:.14em;text-transform:uppercase;
  color:var(--black);text-decoration:none;opacity:.85;white-space:nowrap;
  transition:opacity .15s ease, color .5s ease;
}
nav.on-dark .menu a{color:#fff;}
nav .menu a:hover{opacity:.45;}
nav .menu a.active{opacity:.4;}
.menu-close{
  background:none;border:none;cursor:pointer;color:var(--black);opacity:.85;
  padding:0;margin-left:34px;display:flex;align-items:center;font-size:18px;line-height:1;
  max-width:0;overflow:hidden;
  transition:opacity .15s ease, color .5s ease, max-width .6s ease;pointer-events:none;
}
nav.on-dark .menu-close{color:#fff;}
.menu-close:hover{opacity:.45;}
nav.menu-open .menu-trigger{max-width:0;opacity:0;pointer-events:none;overflow:hidden;}
nav.menu-open .menu{max-width:900px;opacity:1;pointer-events:auto;}
nav.menu-open .menu-close{max-width:40px;opacity:.85;pointer-events:auto;}
nav.nav-solid{
  background:rgba(255,255,255,.9);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);
  border-bottom:1px solid rgba(0,0,0,.06);
}
nav.nav-solid .wordmark,
nav.nav-solid .menu a,
nav.nav-solid .menu-trigger,
nav.nav-solid .menu-close{color:var(--black);}

/* ---------- PAGE SHELL ---------- */
.page{padding:150px var(--pad) 0;min-height:60vh;}
.page-head{margin-bottom:60px;}
.page-eyebrow{
  font-family:var(--sans);font-size:12px;letter-spacing:.18em;text-transform:uppercase;
  color:var(--light);margin-bottom:18px;
}
.page-title{
  font-family:var(--serif);font-weight:500;font-size:clamp(44px,6vw,72px);
  line-height:.98;letter-spacing:.005em;
}
.page-intro{
  font-family:var(--serif);font-style:italic;font-size:clamp(18px,2.2vw,23px);
  color:var(--gray);margin-top:22px;max-width:620px;line-height:1.35;
}

/* ---------- CONTROLS (search + filters) ---------- */
.controls{
  display:flex;justify-content:space-between;align-items:center;gap:30px;
  border-top:1px solid var(--black);border-bottom:1px solid var(--line);
  padding:18px 0;margin-bottom:50px;flex-wrap:wrap;
}
.filters{display:flex;gap:8px;flex-wrap:wrap;align-items:center;}
.filter-btn{
  background:none;border:1px solid var(--line);cursor:pointer;
  font-family:var(--sans);font-size:11px;letter-spacing:.1em;text-transform:uppercase;
  color:var(--gray);padding:8px 15px;transition:all .25s ease;
}
.filter-btn:hover{border-color:var(--black);color:var(--black);}
.filter-btn.active{background:var(--black);border-color:var(--black);color:#fff;}
.filter-group{display:flex;gap:8px;align-items:center;}
.filter-label{
  font-family:var(--sans);font-size:11px;letter-spacing:.12em;text-transform:uppercase;
  color:var(--light);margin-right:4px;
}
.search{
  display:flex;align-items:center;gap:10px;border-bottom:1px solid var(--line);
  padding-bottom:6px;min-width:200px;
}
.search input{
  border:none;outline:none;background:none;flex:1;
  font-family:var(--sans);font-size:14px;color:var(--black);
}
.search input::placeholder{color:var(--light);}
.search svg{flex-shrink:0;}

/* ---------- VIEW TOGGLE ---------- */
.view-toggle{display:flex;gap:0;border:1px solid var(--line);}
.view-toggle button{
  background:none;border:none;cursor:pointer;
  font-family:var(--sans);font-size:11px;letter-spacing:.1em;text-transform:uppercase;
  color:var(--gray);padding:8px 16px;transition:all .25s ease;
}
.view-toggle button.active{background:var(--black);color:#fff;}

/* ---------- FOOTER ---------- */
footer{
  border-top:1px solid var(--line);margin-top:120px;
  padding:60px var(--pad);
  display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:24px;
}
footer .fl{font-family:var(--serif);font-size:19px;font-weight:500;}
footer .fc{font-family:var(--sans);font-size:11px;letter-spacing:.06em;color:var(--light);}
footer a{color:var(--black);text-decoration:none;font-family:var(--sans);font-size:13px;}
footer a:hover{opacity:.5;}

/* ---------- REVEAL ---------- */
.reveal{opacity:0;transform:translateY(20px);transition:opacity .9s ease,transform .9s ease;}
.reveal.in{opacity:1;transform:none;}

/* ---------- MOBILE ---------- */
@media(max-width:760px){
  :root{--pad:24px;}
  nav{padding:20px var(--pad);}
  nav .wordmark{font-size:16px;letter-spacing:.03em;}
  .menu-trigger{display:block;}
  nav .menu{
    position:fixed;inset:0;flex-direction:column;justify-content:center;align-items:center;
    gap:8px;background:#ffffff;max-width:none;width:100vw;height:100vh;
    opacity:0;pointer-events:none;transition:opacity .5s ease;z-index:200;
  }
  nav.menu-open .menu{max-width:none;opacity:1;pointer-events:auto;}
  nav .menu a{
    font-family:var(--serif);font-size:32px;font-weight:500;letter-spacing:.01em;
    text-transform:none;color:#111 !important;opacity:1;padding:10px 0;
  }
  .menu-close{
    position:fixed;top:16px;right:24px;z-index:210;font-size:30px;line-height:1;
    color:#111 !important;max-width:none;overflow:visible;margin:0;opacity:0;pointer-events:none;
  }
  nav.menu-open .menu-close{opacity:.85;pointer-events:auto;}
  nav.menu-open .menu-trigger{opacity:0;pointer-events:none;}
  .page{padding:120px var(--pad) 0;}
  .controls{flex-direction:column;align-items:flex-start;gap:20px;}
  .search{width:100%;}
  footer{margin-top:80px;}
}

