/* ---------- HERO ---------- */
.hero{
  height:100vh;width:100%;
  position:relative;
  display:flex;align-items:flex-end;
  overflow:hidden;
  background:#0e0e0e;
}
.hero-img{
  position:absolute;inset:0;
  width:100%;height:100%;
  object-fit:cover;
  /* placeholder gradient — replace with Xavier's hero work */
  background:
    radial-gradient(ellipse 80% 60% at 50% 35%, #2a2622 0%, #1a1614 45%, #0c0a09 100%);
  opacity:0;
  animation:fadeUp 1.4s ease .2s forwards;
}
.hero-img::after{
  content:'';position:absolute;inset:0;
  background:linear-gradient(to bottom,rgba(0,0,0,.1) 0%,rgba(0,0,0,0) 30%,rgba(0,0,0,0) 70%,rgba(0,0,0,.35) 100%);
}
.hero-placeholder-label{
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  font-family:var(--sans);font-size:11px;letter-spacing:.2em;text-transform:uppercase;
  color:rgba(255,255,255,.3);text-align:center;line-height:2;z-index:2;
  opacity:0;animation:fadeIn 1.4s ease 1s forwards;
}
.hero-caption{
  position:relative;z-index:3;
  padding:0 var(--pad) 48px;
  width:100%;
  opacity:0;animation:fadeUp 1.4s ease .8s forwards;
}
.hero-caption .title{
  font-family:var(--serif);
  font-style:italic;
  font-weight:500;
  font-size:21px;
  color:#fff;
  line-height:1.25;
  max-width:520px;
}
.hero-caption .meta{
  font-family:var(--sans);
  font-size:12px;letter-spacing:.08em;
  color:rgba(255,255,255,.7);
  margin-top:14px;
}
.scroll-cue{
  position:absolute;bottom:40px;left:50%;transform:translateX(-50%);
  z-index:3;width:1px;height:46px;background:rgba(255,255,255,.4);
  overflow:hidden;opacity:0;animation:fadeIn 1.4s ease 1.6s forwards;
}
.scroll-cue::after{
  content:'';position:absolute;top:-46px;left:0;width:1px;height:46px;
  background:#fff;animation:scrollLine 2.4s ease-in-out 2s infinite;
}

/* ---------- SECTION SHELL ---------- */
section.block{padding:65px var(--pad);}
section[id]{scroll-margin-top:90px;}
.section-label{
  font-family:var(--serif);
  font-size:34px;font-weight:500;letter-spacing:.005em;
  text-transform:none;
  color:var(--black);
  margin-bottom:40px;
  line-height:1;
}

/* ---------- EXHIBITIONS (flexible grid — current show earns space) ---------- */
.exh-grid{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:48px;
  align-items:start;
}
.exh-card{cursor:pointer;}
/* span modifiers — current show fills whatever columns the others leave open */
.exh-card.span-3{grid-column:span 3;}
.exh-card.span-2{grid-column:span 2;}
.exh-card.span-1{grid-column:span 1;}
.exh-card .img{
  width:100%;
  height:clamp(360px,30vw,460px);
  background:#e9e7e3;overflow:hidden;position:relative;
}
/* feature cards widen but stay the SAME height as a single card.
   The wide image becomes a letterbox — design a custom hero for this rectangle. */
.exh-card .img > div{
  position:absolute;inset:0;
  transition:transform .7s cubic-bezier(.2,.6,.2,1);
}
.exh-card:hover .img > div{transform:scale(1.03);}
.exh-card .c1{background:radial-gradient(ellipse at 40% 30%,#3a3530,#171411);}
.exh-card .c2{background:radial-gradient(ellipse at 60% 50%,#4a4036,#1d1813);}
.exh-card .c3{background:radial-gradient(ellipse at 50% 60%,#2e2a28,#0f0d0c);}
.exh-card .info{padding:22px 0 0;}
.exh-card .info h3{
  font-family:var(--serif);font-weight:500;font-size:25px;line-height:1.15;
}
/* feature cards get a larger title to match their scale */
.exh-card.span-3 .info h3,
.exh-card.span-2 .info h3{font-size:34px;}
.exh-card .info .sub{
  font-family:var(--sans);font-size:12.5px;letter-spacing:.04em;
  color:var(--light);margin-top:8px;line-height:1.6;
}
.exh-status{
  display:inline-block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;
  color:var(--black);border:1px solid var(--black);
  padding:5px 11px;margin-bottom:14px;
}
.exh-status.muted{
  color:var(--light);border-color:var(--line);
}

/* ---------- ACQUIRE ---------- */
.works-grid{
  display:grid;grid-template-columns:repeat(3,1fr);gap:48px;
}
.work{cursor:pointer;}
.work .img{
  width:100%;aspect-ratio:4/5;background:#ecebe8;overflow:hidden;position:relative;
}
.work .img > div{
  position:absolute;inset:0;transition:transform .7s cubic-bezier(.2,.6,.2,1);
}
.work:hover .img > div{transform:scale(1.03);}
.w1{background:linear-gradient(160deg,#43392f,#191512);}
.w2{background:linear-gradient(160deg,#5b5044,#221c16);}
.w3{background:linear-gradient(160deg,#322d2a,#0f0d0b);}
.work .info{padding-top:18px;}
.work .info .t{font-family:var(--serif);font-style:italic;font-size:21px;font-weight:500;}
.work .info .m{font-family:var(--sans);font-size:12px;color:var(--light);margin-top:6px;letter-spacing:.03em;}
.work .info .act{
  font-family:var(--sans);font-size:12px;letter-spacing:.05em;margin-top:12px;
  display:inline-block;border-bottom:1px solid transparent;transition:border-color .2s ease;
}
.work:hover .info .act{border-color:var(--black);}

.view-all{
  margin-top:64px;
  font-family:var(--sans);font-size:13px;letter-spacing:.06em;
  text-decoration:none;color:var(--black);
  display:inline-flex;align-items:center;gap:9px;
}
.view-all .arrow{transition:transform .3s ease;}
.view-all:hover .arrow{transform:translateX(6px);}

/* ---------- TEXT ---------- */
.text-block{max-width:none;}
.text-row{
  display:flex;justify-content:space-between;align-items:baseline;gap:40px;
  padding:28px 0;border-top:1px solid var(--line);
  cursor:pointer;text-decoration:none;
}
.text-row:last-of-type{border-bottom:1px solid var(--line);}
.text-row .l{flex:1;}
.text-row .l .ti{
  font-family:var(--serif);font-size:28px;font-weight:500;color:var(--black);
  transition:opacity .15s ease;line-height:1.15;
}
.text-row:hover .l .ti{opacity:.5;}
.text-row .r{
  display:flex;align-items:baseline;gap:40px;white-space:nowrap;
}
.text-row .r .dt{
  font-family:var(--sans);font-size:13px;color:var(--gray);letter-spacing:.02em;
}
.text-row .r .ty{
  font-family:var(--sans);font-size:11px;letter-spacing:.13em;text-transform:uppercase;
  color:var(--light);min-width:90px;text-align:right;
}

/* ---------- ARCHIVE BAND ---------- */
.archive-band{
  position:relative;
  width:100%;
  min-height:300px;
  background:#171311;
  overflow:hidden;
  display:flex;align-items:center;
  cursor:pointer;
  text-decoration:none;
}
.archive-band::before{
  content:'';position:absolute;inset:0;
  background:
    radial-gradient(ellipse 70% 90% at 78% 50%, rgba(74,58,44,.55) 0%, rgba(23,19,17,0) 60%),
    linear-gradient(105deg,#120f0d 0%,#1d1714 55%,#241b15 100%);
  transition:transform 1.2s cubic-bezier(.2,.6,.2,1);
}
.archive-band:hover::before{transform:scale(1.04);}
.archive-inner{
  position:relative;z-index:2;
  padding:60px 56px;
  width:100%;
  display:flex;justify-content:space-between;align-items:flex-end;
  gap:40px;
}
.archive-inner .lead .label{
  font-family:var(--sans);font-size:12px;letter-spacing:.18em;text-transform:uppercase;
  color:rgba(255,255,255,.5);margin-bottom:18px;
}
.archive-inner .lead h2{
  font-family:var(--serif);font-weight:500;font-size:34px;
  color:#fff;line-height:1;letter-spacing:.005em;
}
.archive-inner .lead .sub{
  font-family:var(--serif);font-style:italic;font-size:clamp(17px,2vw,21px);
  color:rgba(255,255,255,.6);margin-top:14px;line-height:1.3;max-width:440px;
}
.archive-inner .enter{
  font-family:var(--sans);font-size:13px;letter-spacing:.06em;
  color:#fff;white-space:nowrap;
  display:inline-flex;align-items:center;gap:10px;padding-bottom:6px;
}
.archive-inner .enter .arrow{transition:transform .3s ease;}
.archive-band:hover .enter .arrow{transform:translateX(6px);}

/* ---------- FOOTER ---------- */
footer{
  border-top:1px solid var(--line);
  padding:60px var(--pad);
  display:flex;justify-content:space-between;align-items:center;
  flex-wrap:wrap;gap:24px;
}
footer .fl{font-family:var(--serif);font-size:19px;font-weight:500;}
footer .fc{font-family:var(--sans);font-size:11px;letter-spacing:.06em;color:var(--light);}
footer a{color:var(--black);text-decoration:none;font-family:var(--sans);font-size:13px;}
footer a:hover{opacity:.5;}

/* ---------- REVEAL ---------- */
.reveal{opacity:0;transform:translateY(24px);transition:opacity 1s ease,transform 1s ease;}
.reveal.in{opacity:1;transform:none;}

/* ---------- ANIMATIONS ---------- */
@keyframes fadeUp{from{opacity:0;transform:translateY(24px);}to{opacity:1;transform:none;}}
@keyframes fadeIn{from{opacity:0;}to{opacity:1;}}
@keyframes scrollLine{0%{transform:translateY(0);}100%{transform:translateY(92px);}}

/* ---------- MOBILE ---------- */
@media(max-width:760px){
  :root{--pad:24px;}
  nav{padding:20px var(--pad);}
  nav .wordmark{font-size:16px;letter-spacing:.03em;}
  /* trigger always visible on mobile */
  .menu-trigger{display:block;}
  /* menu becomes a full-screen overlay */
  nav .menu{
    position:fixed;inset:0;
    flex-direction:column;justify-content:center;align-items:center;
    gap:8px;
    background:#ffffff;
    max-width:none;width:100vw;height:100vh;
    opacity:0;pointer-events:none;
    transition:opacity .5s ease;
    z-index:200;
  }
  nav.menu-open .menu{
    max-width:none;opacity:1;pointer-events:auto;
  }
  nav .menu a{
    font-family:var(--serif);
    font-size:32px;font-weight:500;
    letter-spacing:.01em;text-transform:none;
    color:#111 !important;opacity:1;
    padding:10px 0;
  }
  /* close sits top-right ABOVE the overlay */
  .menu-close{
    position:fixed;top:16px;right:24px;
    z-index:210;font-size:30px;line-height:1;
    color:#111 !important;
    max-width:none;overflow:visible;margin:0;
    opacity:0;pointer-events:none;
  }
