  section.block{padding:45px var(--pad);}
  .section-label{font-size:27px;margin-bottom:30px;}
  .works-grid{grid-template-columns:1fr;gap:40px;}
  .exh-grid{grid-template-columns:1fr;gap:40px;}
  .exh-card.span-2,.exh-card.span-3,.exh-card.span-1{grid-column:span 1;}
  .exh-card .img{height:clamp(340px,80vw,420px);}
  .exh-card.span-2 .info h3,.exh-card.span-3 .info h3{font-size:22px;}
  .text-row .r .ty{display:none;}
  .archive-inner{flex-direction:column;align-items:flex-start;gap:28px;padding:40px 32px;}
  .archive-band{min-height:0;}
  .text-row .l .ti{font-size:22px;}
  .scroll-cue{display:none;}
}

page_styles.exhibitions:
.exh-list{border-top:1px solid var(--black);}
.exh-item{
  display:grid;grid-template-columns:1.4fr 1fr auto;gap:40px;align-items:center;
  padding:32px 0;border-bottom:1px solid var(--line);
  text-decoration:none;cursor:pointer;transition:padding .4s ease;
}
.exh-item:hover{padding-left:16px;}
.exh-item .ttl{font-family:var(--serif);font-size:30px;font-weight:500;line-height:1.1;}
.exh-item:hover .ttl{opacity:.55;transition:opacity .2s ease;}
.exh-item .venue{font-family:var(--sans);font-size:13.5px;color:var(--gray);line-height:1.5;}
.exh-item .right{display:flex;align-items:center;gap:28px;white-space:nowrap;}
.exh-item .yr{font-family:var(--sans);font-size:14px;color:var(--gray);}
.exh-item .status{
  font-family:var(--sans);font-size:11px;letter-spacing:.13em;text-transform:uppercase;
  color:var(--black);border:1px solid var(--black);padding:5px 11px;
}
.exh-item .status.muted{color:var(--light);border-color:var(--line);}
.exh-item .status.past{display:none;}
.exh-item.hide{display:none;}
@media(max-width:760px){
  .exh-item{grid-template-columns:1fr;gap:10px;padding:26px 0;}
  .exh-item:hover{padding-left:0;}
  .exh-item .ttl{font-size:24px;}
  .exh-item .right{gap:16px;}
}

page_styles.acquire:
.group-head{
  display:flex;justify-content:space-between;align-items:baseline;
  margin:70px 0 36px;border-bottom:1px solid var(--black);padding-bottom:16px;
}
.group-head:first-of-type{margin-top:0;}
.group-head h2{font-family:var(--serif);font-size:32px;font-weight:500;}
.group-head .note{font-family:var(--sans);font-size:12px;letter-spacing:.04em;color:var(--light);}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:48px 40px;}
.item{cursor:pointer;text-decoration:none;}
.item.hide{display:none;}
.item .img{width:100%;aspect-ratio:4/5;background:#ecebe8;overflow:hidden;position:relative;}
.item .img > div{position:absolute;inset:0;transition:transform .7s cubic-bezier(.2,.6,.2,1);}
.item:hover .img > div{transform:scale(1.03);}
.item .info{padding-top:16px;}
.item .t{font-family:var(--serif);font-style:italic;font-size:21px;font-weight:500;}
.item .m{font-family:var(--sans);font-size:12px;color:var(--light);margin-top:6px;letter-spacing:.03em;line-height:1.5;}
.item .price{font-family:var(--sans);font-size:14px;color:var(--black);margin-top:10px;}
.item .act{
  font-family:var(--sans);font-size:11px;letter-spacing:.1em;text-transform:uppercase;
  margin-top:12px;display:inline-block;border:1px solid var(--black);padding:8px 16px;
  transition:all .25s ease;
}
.item:hover .act{background:var(--black);color:#fff;}
.item .act.inquire{border-color:var(--line);}
.item:hover .act.inquire{background:var(--black);border-color:var(--black);color:#fff;}
.sold{color:var(--light) !important;border-color:var(--line) !important;background:none !important;}
.item:hover .sold{background:none !important;color:var(--light) !important;}
/* gradients */
.g1{background:linear-gradient(160deg,#43392f,#191512);}
.g2{background:linear-gradient(160deg,#5b5044,#221c16);}
.g3{background:linear-gradient(160deg,#322d2a,#0f0d0b);}
.g4{background:radial-gradient(ellipse at 40% 35%,#4a4036,#15110e);}
.g5{background:linear-gradient(150deg,#594b3d,#1c1713);}
.g6{background:radial-gradient(ellipse at 60% 50%,#39322c,#100d0b);}
@media(max-width:760px){
  .grid{grid-template-columns:1fr;gap:40px;}
  .group-head h2{font-size:26px;}
}

page_styles.archive:
.series-block{margin-bottom:80px;}
.series-head{display:flex;align-items:baseline;gap:20px;margin-bottom:30px;}
.series-head h2{font-family:var(--serif);font-size:30px;font-weight:500;}
.series-head .yrs{font-family:var(--sans);font-size:12px;letter-spacing:.1em;color:var(--light);text-transform:uppercase;}
.series-head .count{font-family:var(--sans);font-size:12px;color:var(--light);margin-left:auto;}
.arc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:36px 28px;}
.arc-item{cursor:pointer;text-decoration:none;}
.arc-item.hide{display:none;}
.arc-item .img{width:100%;aspect-ratio:1;background:#ecebe8;overflow:hidden;position:relative;}
.arc-item .img > div{position:absolute;inset:0;transition:transform .7s cubic-bezier(.2,.6,.2,1);}
.arc-item:hover .img > div{transform:scale(1.04);}
.arc-item .t{font-family:var(--serif);font-style:italic;font-size:17px;font-weight:500;margin-top:12px;}
.arc-item .m{font-family:var(--sans);font-size:11px;color:var(--light);margin-top:5px;letter-spacing:.02em;line-height:1.5;}
.arc-item .status-tag{font-family:var(--sans);font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--light);margin-top:4px;}
.series-block.hide{display:none;}
/* year view */
.year-view{display:none;}
.year-view.show{display:block;}
.series-view.hide{display:none;}
.empty{font-family:var(--serif);font-style:italic;font-size:20px;color:var(--light);padding:40px 0;}
/* gradients */
.a1{background:radial-gradient(ellipse at 40% 30%,#3a3530,#171411);}
.a2{background:linear-gradient(160deg,#5b5044,#221c16);}
.a3{background:radial-gradient(ellipse at 60% 50%,#4a4036,#15110e);}
.a4{background:linear-gradient(150deg,#322d2a,#0f0d0b);}
.a5{background:radial-gradient(ellipse at 50% 60%,#594b3d,#1c1713);}
.a6{background:linear-gradient(140deg,#39322c,#100d0b);}
.a7{background:radial-gradient(ellipse at 45% 40%,#463a2e,#14100d);}
.a8{background:linear-gradient(165deg,#4f4439,#1a1511);}
@media(max-width:760px){
  .arc-grid{grid-template-columns:repeat(2,1fr);gap:28px 20px;}
  .series-head h2{font-size:24px;}
}

page_styles.writings:
.w-list{border-top:1px solid var(--black);}
.w-item{
  display:grid;grid-template-columns:1.6fr auto;gap:40px;align-items:baseline;
  padding:30px 0;border-bottom:1px solid var(--line);
  text-decoration:none;cursor:pointer;transition:padding .4s ease;
}
.w-item:hover{padding-left:16px;}
.w-item .l .ti{font-family:var(--serif);font-size:27px;font-weight:500;line-height:1.15;transition:opacity .2s ease;}
.w-item:hover .l .ti{opacity:.55;}
.w-item .l .desc{font-family:var(--sans);font-size:13.5px;color:var(--gray);margin-top:8px;line-height:1.55;max-width:560px;}
.w-item .r{display:flex;align-items:baseline;gap:30px;white-space:nowrap;}
.w-item .r .dt{font-family:var(--sans);font-size:13px;color:var(--gray);}
.w-item .r .ty{font-family:var(--sans);font-size:11px;letter-spacing:.13em;text-transform:uppercase;color:var(--light);min-width:80px;text-align:right;}
.w-item .r .ext{font-size:12px;color:var(--light);}
.w-item.hide{display:none;}
@media(max-width:760px){
  .w-item{grid-template-columns:1fr;gap:12px;padding:24px 0;}
  .w-item:hover{padding-left:0;}
  .w-item .l .ti{font-size:22px;}
  .w-item .r{gap:18px;}
  .w-item .r .ty{display:none;}
}

page_styles.biography:
.bio-top{display:grid;grid-template-columns:.85fr 1.15fr;gap:70px;align-items:start;margin-bottom:90px;}
.portrait{width:100%;aspect-ratio:4/5;background:radial-gradient(ellipse at 45% 35%,#4a4036,#15110e);}
.bio-text .lead{font-family:var(--serif);font-size:clamp(24px,2.8vw,32px);font-weight:500;line-height:1.25;margin-bottom:28px;}
.bio-text p{font-family:var(--serif);font-size:19px;color:#333;line-height:1.7;margin-bottom:20px;}
.tag{font-family:var(--sans);font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:var(--light);margin-bottom:22px;}
/* CV */
.cv{border-top:1px solid var(--black);padding-top:50px;}
.cv-section{margin-bottom:50px;}
.cv-section h3{font-family:var(--sans);font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--light);margin-bottom:22px;}
.cv-row{display:grid;grid-template-columns:90px 1fr;gap:24px;padding:11px 0;border-bottom:1px solid var(--line);}
.cv-row .yr{font-family:var(--sans);font-size:13px;color:var(--light);}
.cv-row .desc{font-family:var(--sans);font-size:14px;color:var(--gray);line-height:1.55;}
.cv-row .desc b{color:var(--black);font-weight:500;}
.press-kit{margin-top:60px;border-top:1px solid var(--black);padding-top:40px;}
.press-kit h3{font-family:var(--sans);font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--light);margin-bottom:20px;}
.press-kit a{display:inline-block;font-family:var(--sans);font-size:14px;margin-right:34px;border-bottom:1px solid var(--black);padding-bottom:2px;text-decoration:none;transition:opacity .2s;}
.press-kit a:hover{opacity:.5;}
@media(max-width:760px){
  .bio-top{grid-template-columns:1fr;gap:36px;margin-bottom:60px;}
  .cv-row{grid-template-columns:60px 1fr;gap:14px;}
}

page_styles.contact:
.contact-wrap{max-width:560px;}
.types{display:flex;gap:28px;margin-bottom:48px;flex-wrap:wrap;}
.type-opt{
  font-family:var(--sans);font-size:14px;letter-spacing:.02em;color:var(--light);
  cursor:pointer;background:none;border:none;padding:0;transition:color .2s ease;
  border-bottom:1px solid transparent;padding-bottom:3px;
}
.type-opt.active{color:var(--black);border-bottom-color:var(--black);font-weight:500;}
.field{margin-bottom:30px;}
.field label{display:block;font-family:var(--sans);font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--light);margin-bottom:10px;}
.field input,.field textarea{
  width:100%;border:none;border-bottom:1px solid var(--line);background:none;outline:none;
  font-family:var(--sans);font-size:16px;color:var(--black);padding:6px 0;resize:none;
  transition:border-color .3s ease;
}
.field input:focus,.field textarea:focus{border-bottom-color:var(--black);}
.send{
  background:none;border:none;cursor:pointer;font-family:var(--sans);font-size:14px;
  letter-spacing:.05em;color:var(--black);padding:0;margin-top:10px;transition:opacity .2s;
  display:inline-flex;align-items:center;gap:9px;
}
.send:hover{opacity:.5;}
.send .arrow{transition:transform .3s ease;}
.send:hover .arrow{transform:translateX(6px);}
.studio-email{margin-top:50px;font-family:var(--sans);font-size:13px;color:var(--light);}
.studio-email a{color:var(--gray);text-decoration:none;border-bottom:1px solid var(--line);}
.confirm{font-family:var(--serif);font-size:24px;font-weight:500;display:none;}
.confirm.show{display:block;}
.form.hide{display:none;}
